1	import { forwardRef } from "react";
2	import Editor from "../Editor";
3	import { useBlobUrls } from "../hooks";
4	import { useEditorContext, useEditorSelector } from "../state";
5	import type { EditorContentProps } from "../types";
6	import type { LocalFile } from "../types/attachment";
7	import type { EditorController } from "../types/editorController";
8	
9	// Imported eagerly (not React.lazy): the editor is the always-present compose
10	// box on the home route, which is already code-split — so deferring the
11	// CodeMirror bundle separately bought nothing and made the editor paint empty
12	// for a beat before its placeholder appeared (a visible flicker on load).
13	
14	/**
15	 * Hosts the CodeMirror Editor behind the EditorController contract. The
16	 * editor serializes into state.content on every change and exposes its
17	 * formatting capability for the focus-mode toolbar.
18	 */
19	export const EditorContent = forwardRef<EditorController, EditorContentProps>(({ placeholder, onSubmit }, ref) => {
20	  const { actions, dispatch } = useEditorContext();
21	  const { createBlobUrl } = useBlobUrls();
22	  const content = useEditorSelector((s) => s.content);
23	  const isFocusMode = useEditorSelector((s) => s.ui.isFocusMode);
24	
25	  const handleFiles = (files: File[]) => {
26	    const localFiles: LocalFile[] = files.map((file) => ({
27	      file,
28	      previewUrl: createBlobUrl(file),
29	      origin: "upload",
30	    }));
31	    localFiles.forEach((localFile) => dispatch(actions.addLocalFile(localFile)));
32	  };
33	
34	  const handleContentChange = (content: string) => {
35	    dispatch(actions.updateContent(content));
36	  };
37	
38	  return (
39	    <div className="w-full flex flex-col flex-1">
40	      <Editor
41	        ref={ref}
42	        className="memo-editor-content"
43	        initialContent={content}
44	        placeholder={placeholder || ""}
45	        isFocusMode={isFocusMode}
46	        onContentChange={handleContentChange}
47	        onFiles={handleFiles}
48	        onSubmit={onSubmit}
49	      />
50	    </div>
51	  );
52	});
53	
54	EditorContent.displayName = "EditorContent";
